INSERT INTO export_task_run (
    task_id, run_no, trigger_type, idempotency_key, request_hash, status, stage,
    expected_count, exported_count, progress, auto_attempt_count, retryable,
    created_at, updated_at, download_count
) VALUES (
    #{taskId}, #{runNo}, #{triggerType}, #{idempotencyKey}, #{requestHash}, #{status}, #{stage},
    #{expectedCount}, #{exportedCount}, #{progress}, #{autoAttemptCount}, #{retryable},
    #{createdAt}, #{updatedAt}, #{downloadCount}
)

mapper.update:
UPDATE export_task_run SET status = 'PROCESSING', stage = 'PREPARING', worker_id = #{workerId},
    execution_token = #{executionToken}, heartbeat_at = #{now}, started_at = COALESCE(started_at, #{now}),
    auto_attempt_count = auto_attempt_count + 1, progress = 1, exported_count = 0,
    failure_code = NULL, failure_message = NULL, retryable = FALSE, updated_at = #{now}
WHERE id = #{runId} AND status = 'PENDING' AND auto_attempt_count < #{maxAttempts}

UPDATE export_task_run SET stage = #{stage}, progress = #{progress}, exported_count = #{exportedCount},
    heartbeat_at = #{now}, updated_at = #{now}
WHERE id = #{runId} AND status = 'PROCESSING' AND execution_token = #{executionToken}

UPDATE export_task_run SET status = 'PENDING', stage = 'RETRY_WAITING', progress = 0,
    exported_count = 0, failure_code = #{failureCode}, failure_message = #{failureMessage},
    retryable = TRUE, worker_id = NULL, execution_token = NULL, heartbeat_at = NULL,
    updated_at = #{now}
WHERE id = #{runId} AND status = 'PROCESSING' AND execution_token = #{executionToken}

UPDATE export_task_run SET status = 'FAILED', stage = 'COMPLETED', failure_code = #{failureCode},
    failure_message = #{failureMessage}, retryable = #{retryable}, completed_at = #{now},
    heartbeat_at = #{now}, updated_at = #{now}
WHERE id = #{runId} AND status = 'PROCESSING' AND execution_token = #{executionToken}

UPDATE export_task_run SET status = 'PENDING', stage = 'RECOVERING', progress = 0, exported_count = 0,
    failure_code = 'WORKER_LOST', failure_message = 'Worker heartbeat timed out; restarting this run',
    retryable = TRUE, worker_id = NULL, execution_token = NULL, heartbeat_at = NULL, updated_at = #{now}
WHERE id = #{runId} AND status = 'PROCESSING' AND execution_token = #{executionToken}
  AND heartbeat_at = #{observedHeartbeatAt}

UPDATE export_task_run SET status = 'FAILED', stage = 'COMPLETED', failure_code = 'WORKER_LOST',
    failure_message = 'Worker heartbeat timed out and automatic attempts are exhausted', retryable = TRUE,
    completed_at = #{now}, updated_at = #{now}
WHERE id = #{runId} AND status = 'PROCESSING' AND execution_token = #{executionToken}
  AND heartbeat_at = #{observedHeartbeatAt}

UPDATE export_task_run SET status = 'FAILED', stage = 'COMPLETED', failure_code = 'FILE_MISSING',
    failure_message = 'Export file does not exist', retryable = FALSE, updated_at = #{now}
WHERE id = #{runId} AND status = 'SUCCESS'
